using AppForSEII.API.Controllers;
using AppForSEII.API.DTOs.RefereeDTOs;
using AppForSEII.API.Models;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;

namespace AppForSEII.UT.RefereeGroupsController_test
{
    public class CreateRefereeGroup_test : AppForSEII4SqliteUT
    {
        // Ids generated by the database (the database is empty when each test starts):
        // game 1 -> football, without referee group
        // game 2 -> football, already has the referee group "Taken" (id 1)
        public CreateRefereeGroup_test()
        {
            var football = new Sport("Football", 11, 3, "11 vs 11 association football", "Rules");
            var basketball = new Sport("Basketball", 5, 2, "5 vs 5 basketball", "Rules");
            _context.Sports.AddRange(football, basketball);
            _context.SaveChanges();

            var captain = new ApplicationUser(
                "1",
                "Elena",
                "Navarro Martínez",
                "elena@uclm.es",
                new DateOnly(1985, 5, 20),
                41,
                Gender.Female)
            {
                EmailConfirmed = true
            };
            _context.ApplicationUsers.Add(captain);
            _context.SaveChanges();

            _context.Referee.AddRange(
                new Referee(5, 3, football.Id) { Id = "2", Name = "Ana", Surname = "Torres" },
                new Referee(4, 2, football.Id) { Id = "3", Name = "Luis", Surname = "Perez" },
                new Referee(3, 1, football.Id) { Id = "4", Name = "Marta", Surname = "Ruiz" },
                // this referee is instructed in basketball, not in football
                new Referee(5, 4, basketball.Id) { Id = "5", Name = "Pablo", Surname = "Gil" },
                // this football referee has 0 years refereeing, so he is not available
                new Referee(2, 0, football.Id) { Id = "6", Name = "Jorge", Surname = "Mora" });
            _context.SaveChanges();

            // TODO: replace both Game objects with the constructor of Game that initializes the properties
            var game1 = new Game("Final", DateTime.Now.AddDays(10), "Stadium Seville", null, football, captain);
            var game2 = new Game("Semifinal", DateTime.Now.AddDays(5), "Stadium Albacete", null, football, captain);
            _context.Games.AddRange(game1, game2);
            _context.SaveChanges();

            _context.RefereeGroup.Add(new RefereeGroup("Taken", "Existing group", "Rules", game2.Id));
            _context.SaveChanges();
        }

        private static RefereeAssignedToDTO Assignment(string refereeId)
        {
            return new RefereeAssignedToDTO(0, refereeId, false, "Main referee", "Leads the match");
        }

        public static IEnumerable<object[]> TestCasesFor_CreateRefereeGroup_Error()
        {
            var allTests = new List<object[]>
            {
                // no referees selected
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO>()),
                    "You must select at least one referee" },
                // the game does not exist
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 999, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("4") }),
                    "The game does not exist" },
                // the game already has a referee group
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 2, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("4") }),
                    "The game already has a referee group" },
                // the name of the group already exists
                new object[] { new RefereeGroupDTO(0, "Taken", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("4") }),
                    "A referee group with that name already exists" },
                // the same referee is selected twice
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("2"), Assignment("3") }),
                    "A referee cannot be selected more than once" },
                // football needs 3 referees
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3") }),
                    "The sport requires at least 3 referees" },
                // referee 5 is instructed in another sport
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("5") }),
                    "Some referees do not exist or are not instructed in the sport of the game" },
                // referee 99 does not exist
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("99") }),
                    "Some referees do not exist or are not instructed in the sport of the game" },
                // referee 6 has 0 years refereeing
                new object[] { new RefereeGroupDTO(0, "Group1", null, null, 1, new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("6") }),
                    "Some referees do not exist or are not instructed in the sport of the game" },
            };

            return allTests;
        }

        [Theory]
        [Trait("LevelTesting", "Unit Testing")]
        [MemberData(nameof(TestCasesFor_CreateRefereeGroup_Error))]
        public async Task CreateRefereeGroup_Error_test(RefereeGroupDTO refereeGroupForCreate, string errorExpected)
        {
            // Arrange
            var mock = new Mock<ILogger<RefereeGroupsController>>();
            ILogger<RefereeGroupsController> logger = mock.Object;
            var controller = new RefereeGroupsController(_context, logger);

            // Act
            var result = await controller.CreateRefereeGroup(refereeGroupForCreate);

            // Assert
            // we check that the response type is BadRequest and obtain the error returned
            var badRequestResult = Assert.IsType<BadRequestObjectResult>(result);
            var problemDetails = Assert.IsType<ValidationProblemDetails>(badRequestResult.Value);

            // we check that the expected error message and actual are the same
            Assert.Equal(errorExpected, problemDetails.Errors.First().Value[0]);
        }

        [Fact]
        [Trait("LevelTesting", "Unit Testing")]
        public async Task CreateRefereeGroup_Success_test()
        {
            // Arrange
            var mock = new Mock<ILogger<RefereeGroupsController>>();
            ILogger<RefereeGroupsController> logger = mock.Object;
            var controller = new RefereeGroupsController(_context, logger);

            var refereeGroupForCreate = new RefereeGroupDTO(0, "Group1", "Main group", "Standard rules", 1,
                new List<RefereeAssignedToDTO> { Assignment("2"), Assignment("3"), Assignment("4") });

            // we expect to have a new referee group (id 2, because "Taken" already has id 1) in the database
            var expectedGroup = new RefereeGroupDTO(2, "Group1", "Main group", "Standard rules", 1,
                new List<RefereeAssignedToDTO>
                {
                    new RefereeAssignedToDTO(2, "2", false, "Main referee", "Leads the match"),
                    new RefereeAssignedToDTO(2, "3", false, "Main referee", "Leads the match"),
                    new RefereeAssignedToDTO(2, "4", false, "Main referee", "Leads the match")
                });

            // Act
            var result = await controller.CreateRefereeGroup(refereeGroupForCreate);

            // Assert
            // we check that the response type is CreatedAtAction and obtain the referee group created
            var createdResult = Assert.IsType<CreatedAtActionResult>(result);
            var actualGroup = Assert.IsType<RefereeGroupDTO>(createdResult.Value);
            Assert.Equal("GetRefereeGroup", createdResult.ActionName);

            // we check that the expected and actual are the same
            Assert.Equal(expectedGroup, actualGroup);

            // we check that the assignments were stored in the database, all of them pending
            Assert.Equal(3, _context.RefereeAssignedTo.Count(a => a.RefereeGroupId == 2 && !a.AcceptedAssignement));
        }
    }
}